using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class NurseEyeAlignment {
 const string Native="Assets/EntityStudioGenerated/RebirthNurseNative";const string Folder=NurseVisualOptimization.Folder;const string Out=NurseVisualOptimization.Out;
 class P {public Vector3 p,n;public Vector2 uv;public BoneWeight w;}
 static BoneWeight Blend(BoneWeight a,BoneWeight b,float t){var values=new Dictionary<int,float>();Action<BoneWeight,float> add=(w,k)=>{int[] ids={w.boneIndex0,w.boneIndex1,w.boneIndex2,w.boneIndex3};float[] ws={w.weight0,w.weight1,w.weight2,w.weight3};for(int i=0;i<4;i++){if(!values.ContainsKey(ids[i]))values[ids[i]]=0;values[ids[i]]+=ws[i]*k;}};add(a,1-t);add(b,t);var top=values.OrderByDescending(v=>v.Value).Take(4).ToArray();float sum=top.Sum(v=>v.Value);return new BoneWeight{boneIndex0=top.Length>0?top[0].Key:0,weight0=top.Length>0?top[0].Value/sum:0,boneIndex1=top.Length>1?top[1].Key:0,weight1=top.Length>1?top[1].Value/sum:0,boneIndex2=top.Length>2?top[2].Key:0,weight2=top.Length>2?top[2].Value/sum:0,boneIndex3=top.Length>3?top[3].Key:0,weight3=top.Length>3?top[3].Value/sum:0};}
 static List<P> Clip(List<P> input,Func<P,float> distance){var output=new List<P>();if(input.Count==0)return output;var a=input[input.Count-1];float da=distance(a);foreach(var b in input){float db=distance(b);if((da>=0)!=(db>=0)){float t=da/(da-db);output.Add(new P{p=Vector3.Lerp(a.p,b.p,t),n=Vector3.Lerp(a.n,b.n,t).normalized,uv=Vector2.Lerp(a.uv,b.uv,t),w=Blend(a.w,b.w,t)});}if(db>=0)output.Add(b);a=b;da=db;}return output;}
 public static void Run(){var report=new List<string>();foreach(string path in new[]{Native+"/RebirthNurse_Authoring.prefab",Native+"/RebirthNurse.prefab"}){
  var model=PrefabUtility.LoadPrefabContents(path);var body=model.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="LOD0");var source=body.sharedMesh;var v=source.vertices;var n=source.normals;var uv=source.uv;var weights=source.boneWeights;var tris=source.triangles;var patches=new List<P>();
  // Landmarks come from the supplied frontal eye texture, not the former height-ratio guess.
  foreach(int side in new[]{-1,1})for(int j=0;j<tris.Length;j+=3){var points=new List<P>();for(int k=0;k<3;k++){int i=tris[j+k];points.Add(new P{p=body.transform.TransformPoint(v[i]),n=body.transform.localToWorldMatrix.inverse.transpose.MultiplyVector(n[i]).normalized,uv=uv[i],w=weights[i]});}if(points.Any(p=>p.p.y<1.60f||p.p.y>1.66f)||points.All(p=>p.p.x*side<.01f))continue;points=Clip(points,p=>p.p.z-.025f);for(int plane=0;plane<16&&points.Count>=3;plane++){float angle=(plane+.5f)*Mathf.PI*2/16;var axis=new Vector2(Mathf.Cos(angle),Mathf.Sin(angle));float cx=side<0?-.0338f:.032f,cy=1.628f;points=Clip(points,p=>Mathf.Cos(Mathf.PI/16)-Vector2.Dot(new Vector2((p.p.x-cx)/.012f,(p.p.y-cy)/.006f),axis));}for(int k=1;k+1<points.Count;k++)patches.AddRange(new[]{points[0],points[k],points[k+1]});}
  if(patches.Count<12)throw new Exception("Eye landmarks missed the supplied eye surfaces");report.Add("Requested patches Y="+patches.Min(p=>p.p.y)+".."+patches.Max(p=>p.p.y));
  foreach(var eye in model.GetComponentsInChildren<SkinnedMeshRenderer>(true).Where(r=>r.name=="NormalEye"||r.name=="FeralEye")){
   var before=NurseAnatomyRender.WorldSkin(eye);report.Add(path+" "+eye.name+" previous centre="+before.bounds.center);UnityEngine.Object.DestroyImmediate(before);
   var mesh=new Mesh{name=eye.sharedMesh.name,indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.vertices=patches.Select(p=>eye.transform.InverseTransformPoint(p.p+p.n*.00025f)).ToArray();mesh.normals=patches.Select(p=>eye.transform.localToWorldMatrix.transpose.MultiplyVector(p.n).normalized).ToArray();mesh.uv=patches.Select(p=>p.uv).ToArray();mesh.boneWeights=patches.Select(p=>p.w).ToArray();eye.bones=body.bones;mesh.bindposes=eye.bones.Select(b=>b.worldToLocalMatrix*eye.transform.localToWorldMatrix).ToArray();mesh.triangles=Enumerable.Range(0,patches.Count).ToArray();mesh.RecalculateTangents();mesh.RecalculateBounds();var target=eye.sharedMesh;target.Clear();target.indexFormat=mesh.indexFormat;target.vertices=mesh.vertices;target.normals=mesh.normals;target.uv=mesh.uv;target.boneWeights=mesh.boneWeights;target.bindposes=mesh.bindposes;target.triangles=mesh.triangles;target.tangents=mesh.tangents;target.bounds=mesh.bounds;eye.sharedMesh=target;EditorUtility.SetDirty(target);UnityEngine.Object.DestroyImmediate(mesh);eye.rootBone=model.transform.Find("Origin");eye.localBounds=target.bounds;report.Add(" corrected eye world bounds="+NurseAnatomyRender.WorldSkin(eye).bounds+" vertices="+target.vertexCount);
  }
  // Own 512 emission mask follows the corrected patches in the new body atlas.
  int size=512;var mask=new Color[size*size];foreach(var p in patches){int x=Mathf.Clamp((int)(p.uv.x*size),0,size-1),y=Mathf.Clamp((int)(p.uv.y*size),0,size-1);for(int dy=-2;dy<=2;dy++)for(int dx=-2;dx<=2;dx++){int xx=x+dx,yy=y+dy;if(xx>=0&&yy>=0&&xx<size&&yy<size)mask[yy*size+xx]=new Color(.211286f,.049165f,.001234f,1);}}
  for(int j=0;j<patches.Count;j+=3){var a=patches[j].uv*size;var b=patches[j+1].uv*size;var c=patches[j+2].uv*size;float d=(b.y-c.y)*(a.x-c.x)+(c.x-b.x)*(a.y-c.y);if(Mathf.Abs(d)<1e-8f)continue;for(int y=Mathf.Max(0,Mathf.FloorToInt(Mathf.Min(a.y,Mathf.Min(b.y,c.y))));y<=Mathf.Min(size-1,Mathf.CeilToInt(Mathf.Max(a.y,Mathf.Max(b.y,c.y))));y++)for(int x=Mathf.Max(0,Mathf.FloorToInt(Mathf.Min(a.x,Mathf.Min(b.x,c.x))));x<=Mathf.Min(size-1,Mathf.CeilToInt(Mathf.Max(a.x,Mathf.Max(b.x,c.x))));x++){float u=((b.y-c.y)*(x+.5f-c.x)+(c.x-b.x)*(y+.5f-c.y))/d,beta=((c.y-a.y)*(x+.5f-c.x)+(a.x-c.x)*(y+.5f-c.y))/d;if(u>=0&&beta>=0&&u+beta<=1)mask[y*size+x]=new Color(.211286f,.049165f,.001234f,1);}}
  var emission=new Texture2D(size,size,TextureFormat.RGBA32,false);emission.SetPixels(mask);emission.Apply();string emissionPath=Folder+"/Atlas_EyeEmission.png";File.WriteAllBytes(emissionPath,emission.EncodeToPNG());AssetDatabase.ImportAsset(emissionPath,ImportAssetOptions.ForceSynchronousImport);var importer=(TextureImporter)AssetImporter.GetAtPath(emissionPath);importer.maxTextureSize=512;importer.sRGBTexture=true;importer.mipmapEnabled=true;importer.SaveAndReimport();
  foreach(string guid in AssetDatabase.FindAssets("t:Material",new[]{Native})){var mat=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(guid));if(mat.name.Contains("NormalEye")){bool feral=mat.name.Contains("_Feral");string tier=mat.name.Contains("Eye_Normal")?"Normal":feral?"Feral":"Special";mat.SetTexture("_Albedo",AssetDatabase.LoadAssetAtPath<Texture2D>(Folder+"/Atlas_Albedo"+(feral?"_Feral":"")+".png"));mat.SetTexture("_Normal",AssetDatabase.LoadAssetAtPath<Texture2D>(Folder+"/Atlas_Normal.png"));mat.SetTexture("_RMOE",AssetDatabase.LoadAssetAtPath<Texture2D>(Folder+"/Atlas_RMOE_"+tier+".png"));EditorUtility.SetDirty(mat);}else if(mat.name.Contains("FeralEye")){mat.SetTexture("_MainTex",AssetDatabase.LoadAssetAtPath<Texture2D>(Folder+"/Atlas_Albedo_Feral.png"));mat.SetTexture("_EmissionMap",AssetDatabase.LoadAssetAtPath<Texture2D>(emissionPath));EditorUtility.SetDirty(mat);}}
  PrefabUtility.SaveAsPrefabAsset(model,path);PrefabUtility.UnloadPrefabContents(model);
 }AssetDatabase.SaveAssets();File.WriteAllLines(Out+"/eye-alignment.txt",report);}
}




